```
#### Benchmark

```rust
use std::time::Instant;

use memchr::memchr2;
use regex::Regex;

fn main() {
    let id = "/from/to/foo/bar/baz.txt";
    let id2 = "/from/to/foo/bar/baz.txt?a=true&foo=bar";
    let regex = Regex::new("\\.txt$").unwrap();
    let regex2 = Regex::new(r"\.txt(?:\?.*)?$").unwrap();

    println!("Id with query");
    let start = Instant::now();
    for i in 0..10000 {
        let url = clean_url(id2);
        let _ = regex.is_match(&url);
    }
    dbg!(&start.elapsed());

    let start = Instant::now();
    for i in 0..10000 {
        let v = regex2.is_match(&id2);
    }
    dbg!(&start.elapsed());

    println!("Id without query");
    let start = Instant::now();
    for i in 0..10000 {
        let url = clean_url(id);
        let _ = regex.is_match(&url);
    }
    dbg!(&start.elapsed());

    let start = Instant::now();
    for i in 0..10000 {
        let v = regex2.is_match(&id);
    }
    dbg!(&start.elapsed());
}

pub fn clean_url(v: &str) -> &str {
    if let Some(index) = memchr2(b'?', b'#', v.as_bytes()) {
        &v[0..index]
    } else {
        v
    }
}
```

#### Result
```bash
Id with query
[src/main.rs:18:5] &start.elapsed() = 235.863µs
[src/main.rs:24:5] &start.elapsed() = 411.165µs
Id without query
[src/main.rs:32:5] &start.elapsed() = 220.042µs
[src/main.rs:38:5] &start.elapsed() = 153.492µs
```

Benchmarking reveals that the memchr and Regex approach exhibits a
performance improvement of 1.7 times when a query is present, but incurs
a 1.4-fold decrease in speed when no query is found. Consequently,
maintaining both methods concurrently may be advantageous, so that user
could choose which method to use according to the scenario.
Also `cleanUrl` is extra dependency free



